import {
  Lucid,
  Blockfrost,
  validatorToAddress,
  Data,
  getAddressDetails,
  validatorToScriptHash,
  applyParamsToScript,
  Constr,
} from "@lucid-evolution/lucid";

// Import centralized price conversion utility
const { convertPriceToLovelace } = require("../utils/price-converter");

// This endpoint compiles the lesson accepted transaction from the request smart contract to the lesson accepted script.
// It builds the datum containing lesson details and the payment to be sent to the script address.
// It returns the unsigned transaction CBOR to the frontend for signing.

const COMPLAINT_SCRIPT_COMPILED_CODE =
  "";

const REQUEST_SCRIPT_COMPILED_CODE =
  "";

const REQUEST_ACCEPTED_SCRIPT_COMPILED_CODE =
  "";

const getValidatorsData = (lucid) => {
  const complaintValidator = {
    type: "PlutusV3",
    script: COMPLAINT_SCRIPT_COMPILED_CODE.trim(),
  };
  const complaintAddress = validatorToAddress(
    process.env.NEXT_PUBLIC_BLOCKFROST_NETWORK,
    complaintValidator
  );
  const complaintHash = validatorToScriptHash(complaintValidator);

  const acceptedValidatorApplied = {
    type: "PlutusV3",
    script: applyParamsToScript(REQUEST_ACCEPTED_SCRIPT_COMPILED_CODE.trim(), [
      complaintHash,
    ]),
  };
  const acceptedAddress = validatorToAddress(
    process.env.NEXT_PUBLIC_BLOCKFROST_NETWORK,
    acceptedValidatorApplied
  );
  const acceptedHash = validatorToScriptHash(acceptedValidatorApplied);
  console.log(
    "Accepted compiled code:",
    REQUEST_ACCEPTED_SCRIPT_COMPILED_CODE.trim()
  );
  console.log("Accepted Validator Applied:", acceptedValidatorApplied);
  console.log("Accepted Validator Hash:", acceptedHash);
  console.log("Accepted Address:", acceptedAddress);

  const requestValidatorApplied = {
    type: "PlutusV3",
    script: applyParamsToScript(REQUEST_SCRIPT_COMPILED_CODE.trim(), [
      acceptedHash,
    ]),
  };
  const requestAddress = validatorToAddress(
    process.env.NEXT_PUBLIC_BLOCKFROST_NETWORK,
    requestValidatorApplied
  );
  return {
    complaintValidator,
    complaintAddress,
    acceptedValidator: acceptedValidatorApplied,
    acceptedAddress,
    requestValidator: requestValidatorApplied,
    requestAddress,
  };
};

const getTeacherLucid = async (address) => {
  const apiKey = process.env.NEXT_PUBLIC_BLOCKFROST_API_KEY || "";
  const apiUrl = process.env.NEXT_PUBLIC_BLOCKFROST_URL || "";
  const lucid = await Lucid(
    new Blockfrost(apiUrl, apiKey),
    process.env.NEXT_PUBLIC_BLOCKFROST_NETWORK
  );
  const utxos = await lucid.utxosAt(address);
  lucid.selectWallet.fromAddress(address, utxos);
  return lucid;
};

function credentialConstr(cred) {
  return cred.type === "Key"
    ? new Constr(0, [cred.hash])
    : new Constr(1, [cred.hash]);
}

function stakeInlineConstr(stakeCred) {
  return new Constr(0, [credentialConstr(stakeCred)]);
}

function maybeStakeConstr(stakeCred) {
  if (!stakeCred) return new Constr(1, []); // None
  return new Constr(0, [stakeInlineConstr(stakeCred)]); // Some(Inline(...))
}

function addressConstr(bech32) {
  const d = getAddressDetails(bech32);
  if (!d?.paymentCredential?.hash)
    throw new Error(`No payment credential for ${bech32}`);

  const pay = credentialConstr(d.paymentCredential);

  const stake = d.stakeCredential?.hash
    ? maybeStakeConstr(d.stakeCredential)
    : new Constr(0, []); // None

  return new Constr(0, [pay, stake]);
}

export function buildDatumExact(
  studentAddr,
  teacherAddr,
  adminAddr,
  lessonStartTimeMs,
  duration,
  delta,
  lockPolicyHex, // "" for lovelace
  lockAssetHex, // "" for lovelace
  lockAmt,
  pricePolicyHex, // "" for lovelace
  priceAssetHex, // "" for lovelace
  priceAmt
) {
  const datum = new Constr(0, [
    addressConstr(studentAddr),
    addressConstr(teacherAddr),
    addressConstr(adminAddr),

    lessonStartTimeMs,
    duration,
    delta,

    lockPolicyHex, // Bytes (hex string) - "" = empty bytes
    lockAssetHex,
    lockAmt,

    pricePolicyHex,
    priceAssetHex,
    priceAmt,
  ]);

  // If you need CBOR hex for .pay.ToContract inline datum:
  const cborHex = Data.to(datum);

  // If you want the “JSON object” view like your example:
  const json = Data.from(cborHex);

  return { datum, cborHex, json };
}

function buildRedeemerDatum() {
  const LessonRequestRedeemer = Data.Enum([
    Data.Object({ Refund: Data.Tuple([]) }),
    Data.Object({
      Accept: Data.Tuple([Data.Integer()]),
    }),
  ]);

  return Data.to({ Accept: [BigInt(0)] }, LessonRequestRedeemer);
}

export default async function handler(req, res) {
  // Basic CORS headers so that http://localhost:3000 can call https://localhost:3000 in dev
  res.setHeader("Access-Control-Allow-Origin", "http://localhost:3000");
  res.setHeader("Access-Control-Allow-Methods", "POST, OPTIONS");
  res.setHeader("Access-Control-Allow-Headers", "Content-Type, Authorization");

  // Handle CORS preflight
  if (req.method === "OPTIONS") {
    console.log("Handling CORS preflight request");
    return res.status(204).end();
  }

  if (req.method !== "POST") {
    console.log("Invalid request method:", req.method);
    return res.status(405).json({ error: "Method not allowed" });
  }

  try {
    const {
      teacherAddress,
      lessonData,
      lessonPaymentUnit = "lovelace",
    } = req.body;
    if (!lessonData || !lessonData.txId || !lessonData.studentWallet)
      throw new Error(
        "Lesson data with valid txId is required or studentWallet is required"
      );
    console.log(
      "Received lesson acceptance request:",
      teacherAddress,
      lessonData,
      lessonPaymentUnit
    );

    const lucid = await getTeacherLucid(teacherAddress);
    // Derive validator address from compiled Plutus script
    const { requestAddress, acceptedAddress, requestValidator } =
      getValidatorsData(lucid);
    console.log("Validator addresses:", requestAddress, acceptedAddress);

    // Define lock data
    const lockUnit =
      process.env.NEXT_PUBLIC_LESSON_LOCK_ASSET_UNIT || "lovelace";
    const lockAmount = parseInt(
      process.env.NEXT_PUBLIC_LESSON_LOCK_LOVELACE_AMOUNT || "10000000"
    );
    if (lockAmount <= 0) {
      throw new Error("Invalid lesson lock lovelace amount configured");
    }
    console.log("Lock data:", lockUnit, lockAmount);

    // Fetch student's UTXOs and build transaction
    const utxos = await lucid.utxosAt(requestAddress);
    console.log("Fetched UTXOs at request validator address:", utxos);
    const inputUtxo = utxos.find((utxo) => utxo.txHash === lessonData.txId);
    if (!inputUtxo) {
      throw new Error("Input UTXO not found in teacher's address");
    }
    console.log("Found input UTXO:", inputUtxo);

    // Convert price from USD cents to lovelace using centralized utility
    const priceInLovelace = await convertPriceToLovelace(lessonData.price);

    // Build transaction amounts
    const txAmount = {};
    txAmount[lockUnit] = (txAmount[lockUnit] || BigInt(0)) + BigInt(lockAmount);
    txAmount[lessonPaymentUnit] =
      (txAmount[lessonPaymentUnit] || BigInt(0)) + BigInt(priceInLovelace);
    console.log("Transaction amounts:", txAmount);

    // Build accepted contract datum
    console.log(
      "Building accepted lesson datum with data:",
      lessonData,
      teacherAddress,
      lockUnit,
      lockAmount,
      lessonPaymentUnit
    );
    let lockPolicyId = "";
    let lockAssetName = "";
    if (lockUnit !== "lovelace") {
      lockPolicyId = lockUnit.slice(0, 56);
      lockAssetName = lockUnit.slice(56);
    }
    let pricePolicyId = "";
    let priceAssetName = "";
    if (lessonPaymentUnit !== "lovelace") {
      pricePolicyId = lessonPaymentUnit.slice(0, 56);
      priceAssetName = lessonPaymentUnit.slice(56);
    }
    const { cborHex: acceptedLessonDatum } = buildDatumExact(
      lessonData.studentWallet,
      teacherAddress,
      process.env.NEXT_PUBLIC_ADMIN_ADDRESS,
      BigInt(lessonData.scheduledUnixtime * 1000),
      BigInt(60),
      BigInt(50),
      lockPolicyId,
      lockAssetName,
      BigInt(lockAmount),
      pricePolicyId,
      priceAssetName,
      BigInt(priceInLovelace)
    );
    //const acceptedLessonDatum = buildTransactionDatum(lessonData.studentWallet, teacherAddress, lessonData, lockUnit, lockAmount, lessonPaymentUnit);
    if (!acceptedLessonDatum) {
      throw new Error("Failed to build accepted lesson datum");
    }
    console.log("Built accepted lesson datum:", acceptedLessonDatum);

    // Create transaction
    const teacherKeyHash =
      getAddressDetails(teacherAddress).paymentCredential.hash;
    if (!teacherKeyHash) {
      throw new Error("Unable to extract teacher key hash from address");
    }
    // Build redeemer datum
    const redeemerDatum = buildRedeemerDatum();
    if (!redeemerDatum) {
      throw new Error("Failed to build redeemer datum");
    }

    let tx = await lucid
      .newTx()
      .collectFrom([inputUtxo], redeemerDatum)
      .pay.ToContract(
        acceptedAddress,
        { kind: "inline", value: acceptedLessonDatum },
        txAmount
      )
      .attach.SpendingValidator(requestValidator)
      .validFrom(Date.now() - 60_000)
      .validTo(Date.now() + 10 * 60_000)
      .addSignerKey(teacherKeyHash)
      .complete();

    return res.status(200).json({
      success: true,
      txCbor: tx.toCBOR(),
    });
  } catch (err) {
    console.error("API error in /api/lessons/accept:", err);
    return res.status(500).json({
      success: false,
      error: err.message || "Internal server error",
    });
  }
}
